/* Wholesale landing and local request builder; shared product catalogue. */
(function(){
'use strict';
const meta={title:'Корзинки для расстойки теста оптом для пекарен — HLEB-FORMA',description:'Ротанговые корзинки для пекарен и хлебных производств. Подбор форм и размеров, комплектация партий, индивидуальное оптовое предложение.',h1:'Корзинки для расстойки хлеба оптом'};
const photo="https://www.oefferl.bio/uploads/_1500xAUTO_crop_center-center_none/meister-wenzel-teigsturz.jpg";
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const limit=n=>Math.max(1,Math.min(99999,Math.floor(Number(n)||1)));
function normalizeItems(products,input){const valid=new Set(products.map(p=>p.id));return Object.fromEntries(Object.entries(input&&typeof input==='object'?input:{}).filter(([id,n])=>valid.has(id)&&Number.isFinite(Number(n))&&Number(n)>0).map(([id,n])=>[id,limit(n)]));}
function total(items){return Object.values(items).reduce((sum,n)=>sum+n,0);}
function search(products,q){q=String(q||'').trim().toLowerCase().replace(/ё/g,'е');const compact=s=>String(s).toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');const sku=compact(q).replace(/^бн/,'bn');if(/^bn\d+$/.test(sku))return products.filter(p=>compact(p.sku)===sku);return products.filter(p=>q.split(/\s+/).every(t=>(p.sku+' '+p.title+' '+p.weightText).toLowerCase().replace(/ё/g,'е').includes(t)));}
// Construct the complete request from the single form; contact data stays in memory.
function buildRequest(products,entries){
 const values=new Map(entries),items=[];
 for(const p of products){
  const key='items['+p.id+']';
  if(!values.has(key))continue;
  const n=Number(values.get(key));
  if(!Number.isInteger(n)||n<1||n>99999)throw Error('Invalid quantity');
  items.push({productId:p.id,sku:p.sku,quantity:n});
 }
 const field=k=>String(values.get(k)??'').trim();
 return {kind:items.length?'batch':'consultation',items,totalQuantity:items.reduce((s,p)=>s+p.quantity,0),contact:{name:field('name'),contact:field('contact'),organization:field('organization'),city:field('city')},comment:field('comment'),consent:field('consent')==='1'};
}
const icons={leaf:'<path d="M5 19C3 8 12 4 21 3c0 10-6 18-16 16ZM5 19l10-10"/>',ruler:'<path d="m3 15 12-12 6 6L9 21zM7 11l3 3m1-7 3 3m1-7 3 3"/>',box:'<path d="M3 7l9-4 9 4v10l-9 4-9-4zM3 7l9 5 9-5m-9 5v9M7 5l10 5"/>',truck:'<path d="M2 5h13v12H2zM15 9h4l3 4v4h-7"/><circle cx="6" cy="18" r="2" fill="white"/><circle cx="18" cy="18" r="2" fill="white"/>',wheat:'<path d="M12 22V7m0 10C5 17 3 13 3 10c5 0 9 2 9 7Zm0-5C5 12 5 6 5 4c5 1 7 3 7 8Zm0 5c7 0 9-4 9-7-5 0-9 2-9 7Zm0-5c7 0 7-6 7-8-5 1-7 3-7 8ZM12 7c-3-3-2-5 0-6 2 1 3 3 0 6Z"/>',factory:'<path d="M3 21V11l6-4v5l6-5v5l6-5v14zM7 21v-4m5 4v-4m5 4v-4M3 7V3h4v6"/>',store:'<path d="M3 10l2-7h14l2 7M3 10v11h18V10M3 10c0 4 5 4 5 0 0 4 8 4 8 0 0 4 5 4 5 0M9 21v-5h6v5"/>',utensils:'<path d="M5 3v7c0 3 5 3 5 0V3M7.5 3v18M18 3c-3 2-4 5-4 9h4m0-9v18"/>'};
function icon(key){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+icons[key]+'</svg>';}
const benefits=[['leaf','Натуральный ротанг'],['ruler','Подбор под вес теста'],['box','Комплектация партии'],['truck','Доставка по России']];
const audiences=[['wheat','Ремесленные пекарни','Формы под ассортимент вашего хлеба.'],['factory','Хлебные производства','Комплектация партий для рабочего процесса.'],['store','Розничные магазины','Подбор ассортимента для перепродажи.'],['utensils','Рестораны и кафе','Инвентарь для собственного хлебопечения.']];
const steps=[['Выбираете ассортимент','Укажите модели и количество или расскажите о задаче.'],['Получаете предложение','Согласуем состав партии, наличие и стоимость.'],['Согласовываете поставку','Обсудим оплату, документы и доставку.'],['Получаете заказ','Комплектуем согласованную партию.']];
const faq=[['Какой минимальный оптовый заказ?','Минимальную партию уточним при согласовании ассортимента и условий закупки.'],['Можно ли заказать разные модели одной партией?','Да. Добавьте необходимые модели и количество каждой в конструкторе заявки.'],['Как рассчитывается оптовая цена?','Стоимость обсуждается индивидуально с учётом состава и объёма партии.'],['Какие документы и способы оплаты доступны?','Сообщите, если закупаете для ИП или юридического лица. Условия оплаты и комплект документов согласуем при расчёте.'],['Как организована доставка?','Укажите город. Способ, стоимость и сроки поставки согласуем с учётом партии и места доставки.'],['Можно ли заказать корзинки с индивидуальным рисунком?','Опишите желаемый рисунок, форму и количество в комментарии. Уточним возможность изготовления.']];
function create({products,app,initialItems={},save=()=>{}}){
 let items=normalizeItems(products,initialItems);const get=id=>products.find(p=>p.id===id);
 const root=()=>app.querySelector('.wh-shop');const query=s=>root()?.querySelector(s);
 function summary(){return {models:Object.keys(items).length,quantity:total(items)};}
 function optionMarkup(q=''){return search(products,q).map(p=>'<option value="'+escape(p.id)+'">'+escape(p.sku+' — '+p.title)+'</option>').join('');}
 function rows(){return Object.entries(items).map(([id,n])=>{const p=get(id);return '<article class="wh-item" data-wh-id="'+escape(id)+'">'+(p.image?'<img src="'+escape(p.image)+'" alt="'+escape(p.exact===false?'Фото аналогичной модели':p.title)+'" loading="lazy" decoding="async">':'<span class="wh-item-icon">'+icon('box')+'</span>')+'<div class="wh-item-copy"><a href="#product-'+escape(id)+'"><strong>'+escape(p.sku)+'</strong> '+escape(p.title)+'</a><small>'+escape(p.weight?p.weightText+' теста':p.weightText)+(p.exact===false?' · Фото аналога':'')+'</small></div><div class="wh-item-controls"><div class="wh-qty"><button type="button" data-wh-action="minus" aria-label="Уменьшить количество '+escape(p.sku)+'"'+(n<=1?' disabled':'')+'>−</button><input type="number" min="1" max="99999" step="1" inputmode="numeric" data-wh-qty name="items['+escape(id)+']" required aria-label="Количество '+escape(p.sku)+'" value="'+n+'"><button type="button" data-wh-action="plus" aria-label="Увеличить количество '+escape(p.sku)+'"'+(n>=99999?' disabled':'')+'>+</button></div><button type="button" class="wh-remove" data-wh-action="remove" aria-label="Удалить '+escape(p.sku)+'">×</button></div></article>';}).join('')||'<div class="wh-empty">'+icon('box')+'<strong>Начните с выбора модели</strong><p>Добавьте нужные корзинки и укажите количество. Если пока не определились, просто опишите задачу в форме.</p></div>';}
 function render(){const s=summary();return `<div class="container wh-shop"><div class="breadcrumb"><a href="v3/index.html">Главная</a> / Оптовым покупателям</div>
 <section class="wh-hero"><div class="wh-hero-copy"><span class="wh-eyebrow">Для пекарен и профессионалов</span><h1>${escape(meta.h1)}</h1><p>Подберём корзинки из натурального ротанга под ваш ассортимент и объёмы выпечки. Соберите партию или обсудите комплектацию с нами.</p><div class="wh-hero-actions"><a class="btn btn-primary" href="#quote-form" data-scroll="quote-form">Собрать оптовую заявку ↗</a><a class="wh-text-link" href="#wh-contact" data-scroll="wh-contact">Нужна консультация?</a></div></div><figure class="wh-hero-photo"><img src="${escape(photo)}" data-wh-photo alt="Корзинки с тестовыми заготовками в профессиональной пекарне" fetchpriority="high" decoding="async"><figcaption>Фото: Öfferl · пример работы пекарни</figcaption></figure></section>
 <div class="wh-benefits">${benefits.map(([k,t])=>'<div>'+icon(k)+'<strong>'+t+'</strong></div>').join('')}</div>
 <section class="wh-section wh-audiences"><h2>Для тех, кто печёт больше</h2><div class="wh-audience-grid">${audiences.map(([k,t,d])=>'<article>'+icon(k)+'<h3>'+t+'</h3><p>'+d+'</p></article>').join('')}</div></section>
 <section class="wh-section wh-request" id="quote-form"><header><span class="wh-eyebrow">Оптовая закупка</span><h2>Соберите оптовую заявку</h2><p>Добавьте нужные модели и оставьте контакты. Состав партии автоматически войдёт в заявку.</p></header>
 <form id="wholesale-form" class="wh-request-grid wh-unified-form" method="post"><div class="wh-builder"><div class="wh-builder-head"><h3>1. Состав партии</h3><button type="button" class="wh-text-link" data-wh-action="clear"${s.models?'':' hidden'}>Очистить</button></div><div class="wh-items" data-wh-items>${rows()}</div>
 <div class="wh-picker"><label for="wh-search">Найти модель</label><input id="wh-search" type="search" placeholder="Название или артикул, например BN 001" maxlength="120"><label for="wh-model">Модель корзинки или аксессуар</label><select id="wh-model">${optionMarkup()}</select><div class="wh-picker-row"><label for="wh-add-qty">Количество, шт.<input id="wh-add-qty" type="text" inputmode="numeric" maxlength="5" value="10" autocomplete="off"></label><button class="btn btn-outline" type="button" data-wh-action="add">+ Добавить модель</button></div><p class="wh-picker-note">Можно добавить разные формы и размеры в одну заявку.</p></div>
 <div class="wh-summary" aria-live="polite"><div><span>Моделей</span><strong data-wh-models>${s.models}</strong></div><div><span>Всего изделий</span><strong><span data-wh-total>${s.quantity}</span> шт.</strong></div><p>Цена и условия поставки согласовываются отдельно. Выбранные товары автоматически включаются в заявку.</p></div></div>
 <div class="wh-contact" id="wh-contact"><h3>2. Контактные данные</h3><p>Оставьте контакт для обсуждения условий. Можно запросить консультацию и без выбранных моделей.</p><div class="wh-form"><div class="wh-fields"><label for="quote-name">Ваше имя *<input id="quote-name" name="name" autocomplete="name" maxlength="120" required placeholder="Имя"></label><label for="quote-contact">Телефон или email *<input id="quote-contact" name="contact" autocomplete="off" maxlength="150" required placeholder="+7… или email"></label><label for="quote-org">Компания<input id="quote-org" name="organization" autocomplete="organization" maxlength="160" placeholder="Название пекарни"></label><label for="quote-city">Город доставки<input id="quote-city" name="city" autocomplete="address-level2" maxlength="120" placeholder="Город"></label></div><label for="quote-comment">Комментарий<textarea id="quote-comment" name="comment" maxlength="2000" rows="4" placeholder="Объёмы выпечки, нужные размеры, рисунок или дополнительные пожелания"></textarea></label><label class="wh-consent"><input type="checkbox" name="consent" value="1" required><span>Согласен на обработку данных для ответа на запрос.</span></label><button class="btn btn-primary wh-submit" type="submit" disabled>Получить предложение ↗</button><small class="wh-form-note">Пока доступна проверка заявки без отправки менеджеру. Контактные данные не сохраняются.</small><div id="lead-success" role="status" aria-live="polite"></div></div></div></form></section>
 <section class="wh-section wh-process"><h2>Как проходит сотрудничество</h2><ol>${steps.map(([t,d],i)=>'<li><b>0'+(i+1)+'</b><h3>'+t+'</h3><p>'+d+'</p></li>').join('')}</ol></section>
 <section class="wh-section wh-faq"><div><span class="wh-eyebrow">Условия сотрудничества</span><h2>Вопросы об оптовых закупках</h2><p>Есть особые требования к партии? Опишите их в заявке.</p><a class="wh-text-link" href="#wh-contact" data-scroll="wh-contact">Задать вопрос ↗</a></div><div class="wh-faq-list">${faq.map(([q,a])=>'<details><summary>'+q+'<span aria-hidden="true">+</span></summary><p>'+a+'</p></details>').join('')}</div></section>
 <section class="wh-final"><div><h2>Готовы обсудить закупку?</h2><p>Подберите формы под ваш хлеб и запросите условия поставки.</p></div><a class="btn btn-primary" href="#quote-form" data-scroll="quote-form">Собрать заявку ↗</a></section>
 <div class="wh-sticky" aria-label="Оптовая заявка"><div><strong><span data-wh-total>${s.quantity}</span> шт.</strong><small><span data-wh-models>${s.models}</span> моделей</small></div><a class="btn btn-primary" href="#wh-contact" data-scroll="wh-contact">Получить цену ↗</a></div></div>`;}
 function sync(){const r=root();if(!r)return;const s=summary();r.querySelectorAll('[data-wh-total]').forEach(el=>el.textContent=s.quantity);r.querySelectorAll('[data-wh-models]').forEach(el=>el.textContent=s.models);const clear=query('[data-wh-action="clear"]');if(clear)clear.hidden=!s.models;const result=query('#lead-success');if(result)result.textContent='';}
 function update(next,{redraw=true}={}){items=normalizeItems(products,next);save({...items});const host=query('[data-wh-items]');if(redraw&&host)host.innerHTML=rows();sync();}
 function setItem(id,n,redraw=true){if(!get(id))return;const next={...items};if(n===0)delete next[id];else next[id]=limit(n);update(next,{redraw});}
 function mount(){const r=root();if(!r)return;query('.wh-submit').disabled=false;const img=query('[data-wh-photo]');if(img&&img.complete&&!img.naturalWidth&&img.getAttribute('src')!== 'v3/assets/hero-bakery.webp')fallback(img);sync();}
 function fallback(img){if(img.getAttribute('src')==='v3/assets/hero-bakery.webp')return;img.src='v3/assets/hero-bakery.webp';const caption=img.parentElement?.querySelector('figcaption');if(caption)caption.textContent='Иллюстрация профессиональной расстойки хлеба';}
 function refreshOptions(q){const model=query('#wh-model');if(!model)return;const current=model.value;model.innerHTML=optionMarkup(q);if(Array.from(model.options).some(x=>x.value===current))model.value=current;const add=query('[data-wh-action="add"]');if(add)add.disabled=!model.options.length;}
 function focusRow(id,action){const row=Array.from(root()?.querySelectorAll('[data-wh-id]')||[]).find(x=>x.dataset.whId===id);const target=row?.querySelector('[data-wh-action="'+action+'"]');if(target&&!target.disabled)target.focus({preventScroll:true});else (row?.querySelector('[data-wh-qty]')||query('#wh-model'))?.focus({preventScroll:true});}
 app.addEventListener('error',e=>{if(e.target.matches?.('[data-wh-photo]'))fallback(e.target);},true);
 app.addEventListener('click',e=>{const r=root(),b=e.target.closest?.('[data-wh-action]');if(!r||!b||!r.contains(b))return;const action=b.dataset.whAction,id=b.closest('[data-wh-id]')?.dataset.whId;
 if(action==='add'){const p=query('#wh-model')?.value,n=limit(query('#wh-add-qty')?.value);if(get(p)){setItem(p,Math.min(99999,(items[p]||0)+n));focusRow(p,'plus');}}
 else if(action==='clear'){update({});query('#wh-search')?.focus();}
 else if(action==='remove'){setItem(id,0);query('#wh-model')?.focus({preventScroll:true});}
 else if(action==='plus'||action==='minus'){setItem(id,limit((items[id]||1)+(action==='plus'?1:-1)));focusRow(id,action);}
 });
 app.addEventListener('keydown',e=>{if(!root()||e.key!=='Enter'||!['wh-search','wh-add-qty'].includes(e.target.id))return;e.preventDefault();if(e.target.id==='wh-add-qty'){query('[data-wh-action="add"]')?.click();}else{query('#wh-model')?.focus();}});
 app.addEventListener('input',e=>{if(!root())return;if(e.target.id==='wh-search')refreshOptions(e.target.value);else if(e.target.matches?.('[data-wh-qty]')){const v=Number(e.target.value);if(Number.isInteger(v)&&v>=1&&v<=99999)setItem(e.target.closest('[data-wh-id]').dataset.whId,v,false);}else if(e.target.closest('#wholesale-form')){const result=query('#lead-success');if(result)result.textContent='';}});
 app.addEventListener('change',e=>{if(!root()||!e.target.matches?.('[data-wh-qty]'))return;const id=e.target.closest('[data-wh-id]').dataset.whId;setItem(id,limit(e.target.value),false);e.target.value=items[id];const row=e.target.closest('[data-wh-id]');row.querySelector('[data-wh-action="minus"]').disabled=items[id]<=1;row.querySelector('[data-wh-action="plus"]').disabled=items[id]>=99999;});
 app.addEventListener('submit',e=>{
  if(e.target.id!=='wholesale-form'||!root())return;
  e.preventDefault();const form=e.target,name=query('#quote-name'),contact=query('#quote-contact');
  if(!name.value.trim()){name.setCustomValidity('Укажите имя.');name.reportValidity();name.setCustomValidity('');return;}
  const v=contact.value.trim();if(!(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)||(/^[+\d()\s.-]+$/.test(v)&&v.replace(/\D/g,'').length>=7))){contact.setCustomValidity('Укажите телефон или email.');contact.reportValidity();contact.setCustomValidity('');return;}
  if(!form.checkValidity())return;
  // FormData contains both contact fields and every selected model's quantity.
  // No endpoint is connected; do not transmit or persist contact data.
  const payload=buildRequest(products,new FormData(form));
  if(!payload.consent)return;
  const lines=payload.items.map(item=>'<li><span><b>'+escape(item.sku)+'</b> · '+escape(get(item.productId).title)+'</span><strong>'+item.quantity+' шт.</strong></li>').join('');
  query('#lead-success').innerHTML='<div class="wh-result"><strong>Заявка подготовлена</strong><p>'+(payload.items.length?'Состав партии автоматически включён в заявку.':'Подготовлен запрос на консультацию.')+'</p>'+(lines?'<ul class="wh-result-items">'+lines+'</ul><div class="wh-result-total"><span>Всего изделий</span><strong>'+payload.totalQuantity+' шт.</strong></div>':'')+'<p>Контактные данные заполнены. Отправка менеджеру пока не подключена.</p></div>';
 });
 return Object.freeze({render,mount,summary,getItems:()=>({...items}),setItem,update});
}
window.HlebWholesale=Object.freeze({meta,photo,create,normalizeItems,total,search,buildRequest});
})();
